from agent import *from models.products import *import redebug = Truedef run(context: dict[str, str], session: Session):   session.sessionbreakers = [SessionBreak(max_requests=20000)]   session.queue(Request('http://www.iceinspace.com.au/reviews.html'), process_productlist, {})def process_productlist(data: Response, context: dict[str, str], session: Session):   for rev in data.xpath("//table[@class='ctable']//td[1]/a"):      newcontext = dict(context)      name = rev.xpath("descendant::text()").string(multiple=True)      category = rev.xpath("preceding::h3[1]//text()").string(multiple=True)      date = rev.xpath("following::td[2]//text()").string(multiple=True)      author = rev.xpath("following::td[1]//text()").string(multiple=True)      url = rev.xpath("@href").string()      if url and name:         newcontext['name'] = name         newcontext['category'] = re_search_once('^(.*)\sReview', category)         newcontext['date'] = date         newcontext['author'] = author         newcontext['url'] = url         session.queue(Request(url), process_review, newcontext)def process_review(data: Response, context: dict[str, str], session: Session):   product = Product()   product.name = context['name']   product.category = context['category']   product.url = context['url']   review = Review()   product.reviews.append(review)   review.title = context['name']   review.type = 'pro'   review.url = context['url']   content = data.xpath("//a[regexp:test(@name,'jump\d+')]").first()   if content:      ssid = content.xpath("@name").string()      if ssid:         product.ssid = re_search_once('(\d+)', ssid)         review.ssid = re_search_once('(\d+)', ssid)      author = context.get('author', None)      if author:         review.authors.append(Person(name=author, ssid=author))      excerpt = content.xpath("following-sibling::h4[1]/preceding-sibling::p//text()").string(multiple=True)      if not(excerpt):         excerpt = content.xpath("following-sibling::h3[1]/preceding-sibling::p//text()").string(multiple=True)      if not(excerpt):         excerpt = content.xpath("following-sibling::p[1]//text()").string(multiple=True)      if excerpt:         review.properties.append(ReviewProperty(type='excerpt', value=excerpt))      conclusion = content.xpath("following-sibling::h4[last()]/following-sibling::p//text()").string(multiple=True)      if not(conclusion):         conclusion = content.xpath("following-sibling::h3[last()]/following-sibling::p//text()").string(multiple=True)      if not(conclusion):         conclusion = content.xpath("following-sibling::p[last()]//text()").string(multiple=True)      if conclusion:         review.properties.append(ReviewProperty(type='conclusion', value=conclusion))   session.emit(product)